const palette={gladiator:['#333548','#ba8065','#ddbd7e'],math:['#213f48','#568b87','#d8ca83'],bugs:['#203c35','#64805b','#e9bd60'],paint:['#35324b','#887397','#d5a6b5'],balloons:['#303a57','#8d718d','#e5bd88'],cafe:['#244143','#72938a','#e6bb7c'],circuit:['#19383c','#3d807f','#dfc680'],gravity:['#27354f','#7d7da4','#9dc9d3'],battle:['#393148','#936f94','#e0b18a'],build:['#3b3c44','#8c7962','#d6b67c'],beat:['#283648','#777997','#c5b19a'],slime:['#213f46','#55918a','#a8ddbb'],dentist:['#303f52','#8c92b0','#d8c4b4'],ninja:['#253849','#64837e','#d1bf92'],castle:['#343b50','#86919c','#cfb47d'],buddy:['#453847','#a08491','#dfbea0'],doodle:['#343c45','#a09c85','#d4ca9a'],robot:['#2c414a','#809e9c','#e4bd84'],wars:['#354344','#7c927a','#ccb37c'],funny:['#413b50','#a28dba','#d6b29c'],monster:['#403748','#8a8d9c','#cbb0d3'],zoo:['#31493e','#819773','#d1be83'],air:['#294252','#6e9c9e','#dfb68d'],spelling:['#33474b','#8da38c','#daca9d'],limit:['#263c48','#668c85','#d5be8c']};
export const PUBLIC_COVER_IDS=Object.freeze(Object.keys(palette));
const line=(d,color='#d3d9ce',w=5)=>`<path d="${d}" fill="none" stroke="${color}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
const box=(x,y,w,h,color,r=12)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${r}" fill="${color}" stroke="#d6ded044" stroke-width="3"/>`;
