const eyes=(x,y)=>`${circle(x-22,y,12,'#f4ecdb')}${circle(x+22,y,12,'#f4ecdb')}${circle(x-20,y+2,5,'#263c48')}${circle(x+20,y+2,5,'#263c48')}`;
const star=(x,y,r,color)=>`<path d="M${x} ${y-r}l${r*.3} ${r*.65} ${r*.7} ${r*.35}-${r*.7} ${r*.3}-${r*.3} ${r*.7}-${r*.3}-${r*.7}-${r*.7}-${r*.3} ${r*.7}-${r*.35}Z" fill="${color}"/>`;
