const leaf=(x,y,a=0)=>`<path d="M0 0Q-55-90 0-140Q65-65 0 0Z" transform="translate(${x} ${y}) rotate(${a})" fill="#789c775e" stroke="#afc8a944" stroke-width="3"/>`;
const bug=(x,y,color,a=0)=>`<g transform="translate(${x} ${y}) rotate(${a})">${[-1,1].map(s=>[0,1,2].map(i=>line(`M${s*35} ${-35+i*38}l${s*30}-14 ${s*18} 18`,'#b8c8ad',5)).join('')).join('')}<ellipse rx="63" ry="84" fill="${color}" stroke="#253e43" stroke-width="7"/>${line('M0-78V80','#334644',4)}${[-1,1].map(s=>circle(s*31,-35,13,'#30484b')+circle(s*29,38,15,'#30484b')).join('')}${circle(0,-80,34,'#2b4146')}${eyes(0,-83)}${line('M-17-107l-13-27M17-107l13-27','#bac8ab',4)}</g>`;
const balloon=(x,y,color,text='')=>`<g transform="translate(${x} ${y})">${line('M0 104C40 145-35 175 0 212','#d0ccc0',3)}<ellipse rx="72" ry="97" fill="${color}" stroke="#304450" stroke-width="5"/>${line('M0-94C-65-40-55 50 0 96M0-94C65-40 55 50 0 96','#31475633',3)}<ellipse cx="-28" cy="-40" rx="10" ry="24" fill="#fff7df66"/><path d="M-7 95h14l7 15H-14Z" fill="${color}"/>${text?`<text y="15" text-anchor="middle" font-family="Outfit,sans-serif" font-size="52" font-weight="800" fill="#263b49">${text}</text>`:eyes(0,0)}</g>`;
const robot=(color='#8fbcba')=>`${line('M402 300l-62 52 10 65M590 302l66 50-10 65','#afc4be',22)}${box(400,265,195,190,color,32)}${box(426,298,143,104,'#2c4855',17)}${gear(496,350,'#d8c294')}${box(385,140,225,128,color,38)}${box(408,165,180,64,'#263f4d',18)}${eyes(498,192)}${line('M498 140v-35','#abbeb8',8)}${circle(498,95,13,'#e0c693')}${box(417,455,51,60,'#697b87')}${box(531,455,51,60,'#697b87')}`;
const tower=(x,y,color)=>`${box(x,y,120,230,color,6)}${[0,1,2].map(i=>box(x+i*45-6,y-24,32,42,color,3)).join('')}${box(x+39,y+65,42,72,'#283d49',20)}`;
const paper=`${box(220,115,570,385,'#d6cfb0',16)}${Array.from({length:8},(_,i)=>line('M260 '+(170+i*39)+'H750','#637d8d33',2)).join('')}`;
function subject(id,a){switch(id){
case 'bugs':return `${leaf(230,510,-40)}${leaf(740,530,40)}${bug(500,305,'#e2bd65',-14)}${bug(735,230,'#8aaab7',25)}${star(325,190,27,a)}`;
case 'balloons':return balloon(325,245,'#dd9ca3')+balloon(520,205,'#a7a0ca','3')+balloon(710,270,'#91c8b2')+line('M100 125Q500 245 900 125','#c4b49566',4);
case 'cafe':return `${box(205,425,590,80,'#8e7964')}${circle(500,267,125,'#8ab8a5')}${eyes(500,238)}${line('M460 302q40 45 80 0','#334751',8)}${circle(385,165,38,'#8ab8a5')}${circle(615,165,38,'#8ab8a5')}<ellipse cx="500" cy="427" rx="160" ry="29" fill="#d9e3d0"/>${box(425,365,150,32,'#ca9f68')}${box(435,341,130,23,'#789567')}${box(442,318,117,24,'#c4b76e')}`;
case 'circuit':return `${box(245,100,510,410,'#234b50',32)}${line('M315 195h160v195h220','#87d7bf',20)}${line('M315 400h95V270h280','#d9a7bb',20)}${[ [315,195],[695,390] ].map(([x,y])=>circle(x,y,29,'#94d9c2')+circle(x,y,10,'#29454f')).join('')}${[[315,400],[690,270]].map(([x,y])=>circle(x,y,29,'#d9a7bb')+circle(x,y,10,'#29454f')).join('')}${Array.from({length:8},(_,i)=>box(275+i*55,125,20,12,'#acbfb2',3)).join('')}`;
case 'robot':return robot()+gear(735,390,a)+line('M235 240l-45 45 55 55 25-25-40-40 22-22','#a9c8c8',24);
case 'dentist':return `${circle(500,315,210,'#aaa2c3')}${eyes(500,190)}${box(310,265,380,180,'#533e56',60)}${[350,420,490,560,630].map((x,i)=>`<path d="M${x-23} 288q-18-18-30 8l12 74q15 25 28-7 15 32 29 7l12-74q-13-25-28-8Z" fill="${i===2?'#a1bd8c':'#eee9d6'}" stroke="#cbd4c9" stroke-width="3"/>`).join('')}${line('M718 414l80-100','#8dcabb',21)}${box(762,284,95,42,'#d0e0d4',12)}`;
case 'slime':return `${box(155,470,690,28,'#8d9d9e',8)}<path d="M360 440Q290 350 390 250Q450 175 515 250Q640 195 662 360Q700 470 570 470H410Z" fill="#85cbb0" stroke="#3f8c82" stroke-width="8"/><ellipse cx="413" cy="307" rx="20" ry="43" fill="#e6f1d066"/>${eyes(505,354)}${line('M473 401q32 30 64 0','#325551',7)}${star(255,275,35,a)}${star(760,185,28,a)}${line('M190 435Q220 330 310 310','#c4dac077',5)}`;
case 'ninja':return `${circle(748,160,64,'#d5d1af66')}${leaf(220,520,-10)}${leaf(830,540,8)}${line('M360 430l-55 50M610 430l55 50','#719e98',34)}${box(370,270,245,187,'#506d80',64)}${circle(490,220,105,'#344b62')}${box(394,184,192,48,'#b8c4bd',14)}${eyes(490,208)}<path d="M392 262l-120 56 105 32 78-55" fill="#a5a0c9"/>${star(720,335,39,'#d9d4bc')}`;
case 'paint':return `${paper}${line('M295 385Q380 180 480 330T715 260','#8c83bc',38)}${circle(330,225,31,'#cf9eab')}${circle(670,405,31,'#83b5a2')}<g transform="rotate(28 620 240)">${box(600,110,35,280,'#d0b579',12)}${box(595,93,45,80,'#ac91be',13)}</g>${star(300,420,27,a)}`;
case 'beat':return `${box(210,155,580,340,'#32455b',30)}${Array.from({length:12},(_,i)=>box(250+i%4*92,255+Math.floor(i/4)*64,72,48,['#829fbb','#b197ba','#98b6aa'][i%3],9)).join('')}${[590,640,690,740].map((x,i)=>line(`M${x} 240v180`,'#92a8af',6)+box(x-15,270+i%3*45,30,18,a,5)).join('')}${line('M270 205v-20m24 35v-48m24 65v-75m24 50v-25m24 30v-44m24 30v-20','#a9c9ba',7)}`;
case 'math':return `${paper}${box(285,205,150,135,'#698f9c',16)}${line('M325 270h70m-35-35v70','#d8e1ce',12)}<path d="M520 380l110-200 110 200Z" fill="#ae9cc0" stroke="#7e718e" stroke-width="8"/>${circle(520,225,36,a)}${line('M305 415h155m75 25h165','#89978a',9)}`;
case 'spelling':return `${box(210,160,580,340,'#546d73',22)}${[0,1,2].map((n)=>`${box(260+n*170,235,145,155,['#adc1a0','#c6a6ad','#cdbc8c'][n],15)}<text x="${332+n*170}" y="340" text-anchor="middle" font-family="Outfit,sans-serif" font-size="95" font-weight="800" fill="#344c53">${['A','B','C'][n]}</text>`).join('')}${line('M315 430h365','#c6d4c2',8)}${star(755,150,28,a)}`;
case 'castle':return tower(245,245,'#84919e')+tower(635,245,'#84919e')+box(350,325,310,155,'#9ba39f',4)+box(445,370,115,110,'#33454f',50)+line('M300 245V120m390 125V120','#c3d0c0',5)+`<path d="M303 120h105l-27 39 27 30H303Z" fill="#a09abb"/><path d="M693 120h105l-27 39 27 30H693Z" fill="#98b6a4"/>`;
case 'wars':return `${tower(680,220,'#73878d')}<g transform="translate(-70 40)">${box(350,265,125,180,'#b4a37c',35)}${circle(412,221,65,'#779199')}${box(360,202,104,42,'#324e57',12)}${eyes(412,220)}${line('M330 320l-35 110M490 300l55-120','#b3bcb4',16)}${box(280,300,80,105,'#7f9a84',25)}</g>${star(595,240,40,a)}${line('M230 485h520','#8a9a8844',12)}`;
case 'gladiator':return `${circle(500,290,155,'#a4a08b22')}${box(385,275,210,190,'#a98569',43)}${circle(490,207,79,'#c1ae84')}${box(422,178,137,61,'#3d4b53',15)}${eyes(490,206)}${line('M395 329l-95 67m295-65 75-120','#bdbdad',22)}${box(280,320,90,135,'#7b8d8e',35)}${line('M673 212l45-104','#cdd4c5',19)}${star(725,140,23,a)}`;
case 'gravity':return `${circle(505,300,160,'#839bbb18')}<ellipse cx="505" cy="300" rx="270" ry="85" transform="rotate(-28 505 300)" fill="none" stroke="#a5b4bf" stroke-width="12"/>${circle(505,300,95,'#8ba8c1')}${circle(478,274,28,'#d6e2d06b')}${line('M210 280v-90m-23 24 23-24 23 24M790 330v90m-23-24 23 24 23-24','#d7c68c',15)}${star(738,177,25,a)}`;
case 'battle':return `${line('M500 145v325','#b9b8c555',4)}${circle(310,300,110,'#928cba')}${circle(690,300,110,'#bb8c9d')}${line('M270 300h80m-40-40v80M650 300h80','#e3ddce',16)}${star(500,300,38,a)}${[200,800].map(x=>star(x,160,20,a)).join('')}`;
case 'build':return `${box(445,360,125,120,'#ab92ae',7)}${box(580,360,125,120,'#bba379',7)}${box(510,230,125,120,'#86aba3',7)}<path d="M500 220l75-98 75 98Z" fill="#cfb77e"/>${circle(275,410,65,'#9f99bf')}${line('M340 380l60-25m-52 62 54-5','#d9c68b',9)}`;
case 'buddy':return `${line('M415 285l-85 70m255-70 70 85M440 420l-15 80m125-80 15 80','#9d89af',28)}${box(400,265,190,180,'#a795bc',46)}${circle(495,190,80,'#ccb493')}${eyes(495,175)}<path d="M425 150l-15-85 65 55m80 0 65-55-15 85" fill="#a795bc"/>${line('M460 225q35 30 70 0','#695b6c',8)}${star(495,340,34,a)}`;
case 'doodle':return `${paper}${line('M290 405l65-160 65 160m-110-50h95M480 400v-130h105v130m-120-145 68-65 68 65','#536b75',10)}${star(685,260,45,'#b89bb2')}${line('M650 430l95-100','#8b7a99',22)}${circle(675,365,25,'#9ab89d')}`;
case 'funny':return `${box(220,130,560,365,'#536574',30)}${circle(500,305,125,'#c2a7b1')}${eyes(500,275)}${line('M440 340q60 60 120 0','#66516d',10)}${box(270,178,90,55,'#95b8b2',12)}${star(700,190,25,a)}${line('M270 450h75m310 0h75','#d6d2be',6)}`;
case 'monster':return `${circle(500,310,160,'#a39abd')}<path d="M370 210l-28-100 104 48m108 0 104-48-28 100" fill="#a39abd"/>${eyes(500,260)}${line('M430 354q70 70 140 0','#4e5268',13)}${circle(377,320,25,'#cb9cab88')}${circle(623,320,25,'#cb9cab88')}${star(720,385,28,a)}`;
case 'zoo':return `${leaf(220,520,-20)}${leaf(800,520,20)}${circle(500,325,135,'#c4ab7e')}${circle(403,213,48,'#b89d72')}${circle(597,213,48,'#b89d72')}${eyes(500,285)}${circle(500,335,28,'#665b53')}${line('M466 378q34 26 68 0','#665b53',7)}${[240,745].map((x,i)=>`${circle(x,350,50,i?'#8db3a3':'#a6a7b9')}${eyes(x,340)}`).join('')}`;
case 'air':return `${line('M190 430Q380 410 520 200T820 205','#b9dcd0',18)}${line('M210 455Q400 435 540 225T840 230','#c3c4d344',6)}${circle(340,280,65,'#cbaa7a')}${circle(680,370,70,'#9ebda2')}${line('M318 216l30-38m317 120 30-36','#6a927b',12)}${star(770,168,35,a)}`;
case 'limit':return `${tower(610,185,'#879c9c')}${leaf(260,510,-20)}${leaf(350,500,20)}${line('M430 485l50-125 75 50 65 75','#9eb8a4',19)}${box(425,280,115,130,'#7b98a9',25)}${circle(482,242,43,'#b9b3a1')}${line('M530 320l80-85','#d5c9a4',13)}${star(745,155,27,a)}`;
 default:return '';
}}
export function publicCoverArt(id){if(!Object.hasOwn(palette,id))return '';const [dark,mid,accent]=palette[id],prefix='lba-cover-'+id;return `<svg viewBox="0 0 1000 600" aria-hidden="true" xmlns="http://www.w3.org/2000/svg"><defs><linearGradient id="${prefix}" x2="1" y2="1"><stop stop-color="${dark}"/><stop offset="1" stop-color="${mid}"/></linearGradient></defs><rect width="1000" height="600" rx="30" fill="url(#${prefix})"/><circle cx="730" cy="160" r="240" fill="${accent}" opacity=".07"/><path d="M0 490Q260 390 500 490T1000 470V600H0Z" fill="${dark}" opacity=".65"/>${Array.from({length:12},(_,i)=>circle(70+i*79,75+(i*73)%430,2,accent+'55')).join('')}${subject(id,accent)}<path d="M50 545h900" stroke="${accent}" stroke-width="2" opacity=".2"/></svg>`;}
